module permutation_swapper (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    output reg possible,\n    output reg valid,\n    output reg [7:0] a,\n    output reg [7:0] b,\n    output reg done\n);\n\n// State definitions\nlocalparam [3:0] IDLE    = 4'd0;\nlocalparam [3:0] CHECK   = 4'd1;\nlocalparam [3:0] X0_FWD  = 4'd2;\nlocalparam [3:0] X0_SWAP = 4'd3;\nlocalparam [3:0] X0_BWD  = 4'd4;\nlocalparam [3:0] X1_FWD  = 4'd5;\nlocalparam [3:0] X1_SWAP = 4'd6;\nlocalparam [3:0] X1_BWD  = 4'd7;\nlocalparam [3:0] FINAL1  = 4'd8;\nlocalparam [3:0] FINAL2  = 4'd9;\nlocalparam [3:0] FINAL3  = 4'd10;\nlocalparam [3:0] FINAL4  = 4'd11;\nlocalparam [3:0] NEXT_I  = 4'd12;\nlocalparam [3:0] DONE    = 4'd13;\n\nreg [3:0] state;\nreg [7:0] i_reg;      // current block start index (0-indexed)\nreg [7:0] j_reg;      // counter for j loops\nreg [1:0] x_reg;      // current x (0 or 1)\nreg [1:0] final_cnt;  // 0..3 for final swaps\nreg [7:0] n_reg;      // stored n\n\n// Helper: n mod 4\nwire [1:0] n_mod4 = n[1:0];\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state      <= IDLE;\n        possible   <= 1'b0;\n        valid      <= 1'b0;\n        a          <= 8'd0;\n        b          <= 8'd0;\n        done       <= 1'b0;\n        i_reg      <= 8'd0;\n        j_reg      <= 8'd0;\n        x_reg      <= 2'd0;\n        final_cnt  <= 2'd0;\n        n_reg      <= 8'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                valid <= 1'b0;\n                if (start) begin\n                    n_reg <= n;\n                    state <= CHECK;\n                end\n            end\n\n            CHECK: begin\n                if (n_mod4 == 2'd0 || n_mod4 == 2'd1) begin\n                    possible <= 1'b1;\n                    i_reg <= {6'd0, n_mod4};\n                    if ({6'd0, n_mod4} >= n_reg) begin\n                        state <= DONE;\n                    end else begin\n                        state <= X0_FWD;\n                        j_reg <= 8'd0;\n                    end\n                end else begin\n                    possible <= 1'b0;\n                    state <= DONE;\n                end\n            end\n\n            X0_FWD: begin\n                if (j_reg < i_reg) begin\n                    valid <= 1'b1;\n                    a <= j_reg + 8'd1;\n                    b <= i_reg + 8'd1;\n                    j_reg <= j_reg + 8'd1;\n                end else begin\n                    valid <= 1'b0;\n                    j_reg <= 8'd0;\n                    state <= X0_SWAP;\n                end\n            end\n\n            X0_SWAP: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd1;\n                b <= i_reg + 8'd2;\n                state <= X0_BWD;\n            end\n\n            X0_BWD: begin\n                if (j_reg < i_reg) begin\n                    valid <= 1'b1;\n                    a <= j_reg + 8'd1;\n                    b <= i_reg + 8'd2;\n                    j_reg <= j_reg + 8'd1;\n                end else begin\n                    valid <= 1'b0;\n                    j_reg <= 8'd0;\n                    state <= X1_FWD;\n                end\n            end\n\n            X1_FWD: begin\n                if (j_reg < i_reg) begin\n                    valid <= 1'b1;\n                    a <= j_reg + 8'd1;\n                    b <= i_reg + 8'd3;\n                    j_reg <= j_reg + 8'd1;\n                end else begin\n                    valid <= 1'b0;\n                    j_reg <= 8'd0;\n                    state <= X1_SWAP;\n                end\n            end\n\n            X1_SWAP: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd3;\n                b <= i_reg + 8'd4;\n                state <= X1_BWD;\n            end\n\n            X1_BWD: begin\n                if (j_reg < i_reg) begin\n                    valid <= 1'b1;\n                    a <= j_reg + 8'd1;\n                    b <= i_reg + 8'd4;\n                    j_reg <= j_reg + 8'd1;\n                end else begin\n                    valid <= 1'b0;\n                    final_cnt <= 2'd0;\n                    state <= FINAL1;\n                end\n            end\n\n            FINAL1: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd1;\n                b <= i_reg + 8'd4;\n                final_cnt <= 2'd1;\n                state <= FINAL2;\n            end\n\n            FINAL2: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd2;\n                b <= i_reg + 8'd3;\n                final_cnt <= 2'd2;\n                state <= FINAL3;\n            end\n\n            FINAL3: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd1;\n                b <= i_reg + 8'd3;\n                final_cnt <= 2'd3;\n                state <= FINAL4;\n            end\n\n            FINAL4: begin\n                valid <= 1'b1;\n                a <= i_reg + 8'd2;\n                b <= i_reg + 8'd4;\n                state <= NEXT_I;\n            end\n\n            NEXT_I: begin\n                valid <= 1'b0;\n                i_reg <= i_reg + 8'd4;\n                if (i_reg + 8'd4 < n_reg) begin\n                    state <= X0_FWD;\n                    j_reg <= 8'd0;\n                end else begin\n                    state <= DONE;\n                end\n            end\n\n            DONE: begin\n                done <= 1'b1;\n                valid <= 1'b0;\n                state <= DONE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule